    private fun b(x: Int): Int = x and 0xFF

    fun add(x: Int, y: Int): Int = x xor y
    fun sub(x: Int, y: Int): Int = x xor y

    fun mul(x: Int, y: Int): Int {
        val xi = b(x); val yi = b(y)
        if (xi == 0 || yi == 0) return 0
        return exp[b(log[xi].toInt()) + b(log[yi].toInt())].toInt() and 0xFF
    }

    fun div(x: Int, y: Int): Int {
        val xi = b(x); val yi = b(y)
        require(yi != 0) { "division by zero in GF" }
        if (xi == 0) return 0
        return exp[(b(log[xi].toInt()) + 255 - b(log[yi].toInt())) % 255].toInt() and 0xFF
    }

    fun pow(x: Int, power: Int): Int {
        var i = b(log[b(x)].toInt())
        i = (i * power) % 255
        if (i < 0) i += 255
        return exp[i].toInt() and 0xFF
    }

    fun inverse(x: Int): Int {
        return exp[255 - b(log[b(x)].toInt())].toInt() and 0xFF
    }
